import os
import unicodedata
import hashlib
import hmac
import secrets
from flask import Flask, request, jsonify, abort
from functools import wraps

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

# --- Secure password hashing helpers (PBKDF2-HMAC-SHA256 with per-user salt) ---
PBKDF2_ITERATIONS = 200_000


def hash_password(password: str, salt: bytes = None) -> str:
    """Return 'salt_hex$hash_hex' using PBKDF2-HMAC-SHA256."""
    if salt is None:
        salt = secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, PBKDF2_ITERATIONS)
    return salt.hex() + '$' + dk.hex()


def verify_password(password: str, stored: str) -> bool:
    try:
        salt_hex, hash_hex = stored.split('$', 1)
        salt = bytes.fromhex(salt_hex)
    except (ValueError, TypeError):
        return False
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, PBKDF2_ITERATIONS)
    return hmac.compare_digest(dk.hex(), hash_hex)


# Simulated user store (passwords stored as PBKDF2 hashes)
USERS = {
    'admin': {'password_hash': hash_password('admin_secret_2024!'), 'role': 'admin'},
    'alice': {'password_hash': hash_password('alice_pass_secure!'), 'role': 'user'},
}

# Access control: users can only access /data/public/** and /data/users/<own_name>/**
# Admins can access everything under /data/
BASE_DIR = '/data'


def authenticate(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth = request.authorization
        if not auth or auth.username not in USERS:
            abort(401)
        stored = USERS[auth.username]['password_hash']
        if not auth.password or not verify_password(auth.password, stored):
            abort(401)
        request.user = auth.username
        request.role = USERS[auth.username]['role']
        return f(*args, **kwargs)
    return decorated


def normalize_path(path_str):
    """Normalize path consistently for both authorization and filesystem access.
    Uses NFKC normalization throughout for consistency."""
    # NFKC: compatibility decomposition + canonical composition
    normalized = unicodedata.normalize('NFKC', path_str)
    # Remove any null bytes
    normalized = normalized.replace('\x00', '')
    # Collapse multiple slashes
    parts = [p for p in normalized.split('/') if p]
    # Resolve . and ..
    resolved = []
    for part in parts:
        if part == '.':
            continue
        elif part == '..':
            if resolved:
                resolved.pop()
        else:
            resolved.append(part)
    return '/' + '/'.join(resolved)


def check_access(user, role, normalized_path):
    """Check if user has access to the normalized path."""
    # Admin has full access
    if role == 'admin':
        return True
    # Path must start with /data/
    if not normalized_path.startswith('/data/'):
        return False
    # Users can access /data/public/
    if normalized_path.startswith('/data/public/'):
        return True
    # Users can access their own directory
    if normalized_path.startswith(f'/data/users/{user}/'):
        return True
    return False


@app.route('/api/files', methods=['GET'])
@authenticate
def get_file():
    """Retrieve file contents. Path is provided as query parameter."""
    file_path = request.args.get('path', '')
    if not file_path:
        return jsonify({'error': 'path parameter required'}), 400

    # Normalize path once, use for both authz and filesystem
    safe_path = normalize_path(file_path)

    # Check access control
    if not check_access(request.user, request.role, safe_path):
        return jsonify({'error': 'access denied'}), 403

    # Safety check - must be under BASE_DIR
    if not safe_path.startswith(BASE_DIR + '/'):
        return jsonify({'error': 'invalid path'}), 400

    # Use os.path.realpath to resolve symlinks
    real_path = os.path.realpath(safe_path)
    if not real_path.startswith(BASE_DIR + '/'):
        return jsonify({'error': 'invalid path'}), 400

    # Read file
    try:
        if os.path.isfile(real_path):
            with open(real_path, 'r') as f:
                content = f.read()
            return jsonify({'path': safe_path, 'content': content})
        else:
            return jsonify({'error': 'file not found'}), 404
    except (IOError, OSError) as e:
        return jsonify({'error': 'read error'}), 500


@app.route('/api/files', methods=['PUT'])
@authenticate
def put_file():
    """Write file contents."""
    data = request.get_json()
    if not data or 'path' not in data or 'content' not in data:
        return jsonify({'error': 'path and content required'}), 400

    file_path = data['path']
    content = data['content']

    # Normalize path once, use for both authz and filesystem
    safe_path = normalize_path(file_path)

    # Check access
    if not check_access(request.user, request.role, safe_path):
        return jsonify({'error': 'access denied'}), 403

    # Ensure under BASE_DIR
    if not safe_path.startswith(BASE_DIR + '/'):
        return jsonify({'error': 'invalid path'}), 400

    # Use os.path.realpath for the directory to prevent symlink attacks
    dir_path = os.path.dirname(safe_path)
    if os.path.exists(dir_path):
        real_dir = os.path.realpath(dir_path)
        # Use BASE_DIR + '/' (or exact match) to prevent prefix confusion
        if not (real_dir == BASE_DIR or real_dir.startswith(BASE_DIR + '/')):
            return jsonify({'error': 'invalid path'}), 400

    # Write
    try:
        os.makedirs(os.path.dirname(safe_path), exist_ok=True)
        with open(safe_path, 'w') as f:
            f.write(content)
        return jsonify({'path': safe_path, 'status': 'written'})
    except (IOError, OSError):
        return jsonify({'error': 'write error'}), 500


if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080, debug=False)
